import { describe, expect, it } from "vitest";
import { createTuGame, dealBatch, isSupportedTuSeed, replayTu, resumeTuGame, tuSeed, tuSeedVersion } from "@/lib/tu";
import recorded from "../fixtures/tu-v5-run.json";

// Captured with HEAD's unmodified v5 engine/deal, not regenerated by the code under test.
describe("D189 live v5 compatibility", () => {
  it("replays the recorded 13-oven v5 run to its exact original score", () => {
    expect(recorded.score).toBe(87_030);
    expect(replayTu(recorded.seed, recorded.tiers, recorded.taps)).toEqual({
      score: recorded.score, batch: 14, over: true, taps: recorded.taps.length,
    });
  });

  it("resumes a serialized v5 save at the original state, then continues beyond oven 12", () => {
    const save = JSON.parse(JSON.stringify({ seed: recorded.seed, tiers: recorded.tiers,
      taps: recorded.taps.slice(0, recorded.checkpoint.length) }));
    const game = resumeTuGame(save.seed, save.tiers, save.taps);
    expect(game.state()).toEqual(recorded.checkpoint.state);
    expect(game.state().orderPoints).toEqual([210, 210]);
    for (const tap of recorded.taps.slice(recorded.checkpoint.length)) {
      expect(tap.id === 0 ? game.stop() : game.tap(tap.id)).not.toBeNull();
    }
    expect(game.score).toBe(recorded.score);
    expect(game.over).toBe(true);
  });

  it("selects generation by seed and only issues new v6 seeds", () => {
    expect(tuSeedVersion(tuSeed("abc"))).toBe(6);
    expect(dealBatch(recorded.seed, 8, 4).tiles).toHaveLength(72);
    expect(dealBatch(tuSeed("abc"), 8, 4).tiles).toHaveLength(84);
    expect(isSupportedTuSeed(recorded.seed)).toBe(true);
    expect(isSupportedTuSeed(tuSeed("abc"))).toBe(true);
    for (const seed of ["abc", "v1.abc", "v2.abc", "v3.abc", "v4.abc", "v7.abc", "v99.abc"]) {
      expect(isSupportedTuSeed(seed)).toBe(false);
    }
    expect(() => createTuGame({seed: "v4.abc", tiers: recorded.tiers})).toThrow(/unsupported/);
  });
});
